/* eslint-disable max-classes-per-file */

import { createRequire } from 'module';
import fsExtra from 'fs-extra';
import { proxy } from 'comlink';
import { Logger } from '@teambit/logger';
import { HarmonyWorker } from '@teambit/worker';
import { Workspace, WorkspaceAspect } from '@teambit/workspace';
import { DependencyResolverMain, DependencyResolverAspect } from '@teambit/dependency-resolver';
import {
  Tester,
  CallbackFn,
  TesterContext,
  Tests,
} from '@teambit/tester';
import { DevFilesAspect, DevFilesMain } from '@teambit/dev-files';
import { EnvContext, EnvHandler } from '@teambit/envs';
import { startVitest, VitestPackageInstaller } from 'vitest/node';

import type { VitestWorker } from './vitest.worker.js';
import type { VitestOptions, VitestTesterOptions } from './vitest-options.js';

import {
  applySpecPatterns,
  splitNegatedPatterns,
  getConfig,
} from './config-utils.js';
import {
  type VitestFile,
  getResultFromFiles,
} from './report-utils.js';
import {
  checkCoverageThresholds,
} from './coverage-utils.js';
import { HangGuardReporter } from './hang-guard.js';

const { readFileSync, readJsonSync } = fsExtra;

const require = createRequire(import.meta.url);

export class VitestTester implements Tester {
  constructor(
    readonly id: string,
    readonly configPath: string,
    private vitestWorker: HarmonyWorker<VitestWorker>,
    private logger: Logger,
    private workspace: Workspace | undefined,
    private depResolver: DependencyResolverMain,
    private devFiles: DevFilesMain,
    private opts: VitestTesterOptions = {}
  ) {}

  static from(options: VitestOptions): EnvHandler<Tester> {
    const id = options.name || 'vitest-tester';
    return (context: EnvContext) => {
      const logger = context.createLogger(id);
      const worker = context.createWorker<VitestWorker>(
        id,
        require.resolve('./vitest.worker')
      );
      let workspace: Workspace | undefined;
      try {
        workspace = context.getAspect<Workspace>(WorkspaceAspect.id);
      } catch (err) {
        logger.info('unable to load workspace aspect');
      }
      const depResolver = context.getAspect<DependencyResolverMain>(DependencyResolverAspect.id);
      const devFiles = context.getAspect<DevFilesMain>(DevFilesAspect.id);
      return new VitestTester(
        id,
        options.config,
        worker,
        logger,
        workspace,
        depResolver,
        devFiles,
        options,
      );
    };
  }

  displayName = 'Vitest';

  version() {
    const filePath = require.resolve('vitest/package.json');
    const vitestPackageInfo = readJsonSync(filePath);
    return vitestPackageInfo.version;
  }

  displayConfig() {
    return readFileSync(this.configPath, 'utf8');
  }

  private onTestRunCompleteCb: CallbackFn | undefined;

  async onTestRunComplete(callback: CallbackFn) {
    this.onTestRunCompleteCb = callback;
  }

  /**
   * Resolve the no-progress window (ms) after which a run is considered hung.
   * Precedence: BIT_VITEST_HANG_TIMEOUT env var > `hangTimeout` option >
   * `testTimeout + 5000` (floored at 15000). The default sits comfortably above
   * the per-test `testTimeout` so async/finite-sync tests fail on their own
   * (emitting progress) before the guard ever fires — it only catches runs that
   * truly stop making progress.
   */
  private resolveHangTimeout(viteConfig: any): number {
    const envOverride = Number(process.env.BIT_VITEST_HANG_TIMEOUT);
    if (Number.isFinite(envOverride) && envOverride > 0) return envOverride;
    const opt = (this.opts as any).hangTimeout;
    if (Number.isFinite(opt) && opt > 0) return opt;
    const testTimeout = Number(viteConfig?.test?.testTimeout) || 0;
    return Math.max(testTimeout + 5000, 15000);
  }

  async test(context: TesterContext): Promise<Tests> {
    if (this.opts.coverage !== false && context.release) {
      context.coverage = true;
    }

    const viteConfig = await getConfig(
      this.configPath,
      context,
      this.depResolver,
      this.opts,
      false
    );

    if (context.coverage) {
      for (const component of context.components) {
        const patterns = this.devFiles.getDevPatterns(component);
        // `!` patterns break coverage in vitest excludes — see splitNegatedPatterns
        // @ts-ignore
        viteConfig.test!.coverage!.exclude!.push(...splitNegatedPatterns(patterns).include);
      }

      // @ts-ignore
      viteConfig.test!.coverage!.exclude!.push('**/*.bit-app.*');
    }

    applySpecPatterns(viteConfig, this.opts, context);

    if ((context as any).updateSnapshot) {
      // @ts-ignore
      viteConfig.test!.update = true;
    }

    if ((context as any).watch) {
      // @ts-ignore
      viteConfig.test!.watch = true;
    }

    // skip installation checks
    const installErrors: Error[] = [];
    class CustomPackageInstaller extends VitestPackageInstaller {
      async ensureInstalled(dependency: string): Promise<boolean> {
        try {
          require.resolve(dependency, { paths: [viteConfig.root!] });
        }
        catch (err) {
          installErrors.push(err as Error);
          return false;
        }
        return true;
      }
    }

    // --- hang guard -------------------------------------------------------
    // A test stuck in synchronous code (an infinite loop) blocks its worker's
    // event loop, so Vitest's in-worker `testTimeout` can never fire and the
    // run hangs forever. This is a documented Vitest limitation (see
    // hang-guard.ts for links). We attach a reporter that records run progress
    // and, since this orchestrator process is NOT blocked by the stuck worker,
    // poll it here; once the run is idle past `hangTimeout` we abort it.
    const hangGuard = new HangGuardReporter();
    const testConfig = (viteConfig as any).test;
    const existingReporters = testConfig.reporters;
    testConfig.reporters = existingReporters
      ? [...(Array.isArray(existingReporters) ? existingReporters : [existingReporters]), hangGuard]
      : [['default', {}], hangGuard];
    // A force-terminated `forks` worker is reparented by the OS and keeps
    // spinning the CPU; a worker thread dies with its parent. Default to
    // `threads` so aborting a hung run never leaves an orphan. Envs that set
    // `pool` explicitly are respected.
    if (!testConfig.pool) testConfig.pool = 'threads';

    const runPromise = startVitest('test', undefined, undefined, viteConfig as any, {
      packageInstaller: new CustomPackageInstaller()
    });

    let hangTimer: ReturnType<typeof setInterval> | undefined;
    if (!context.watch) {
      const hangTimeout = this.resolveHangTimeout(viteConfig);
      hangTimer = setInterval(() => {
        if (Date.now() - hangGuard.lastProgress < hangTimeout) return;
        clearInterval(hangTimer);
        this.logger.console(
          `\n[vitest] Test run made no progress for ${hangTimeout}ms. A test is likely stuck in ` +
          `synchronous code that Vitest's in-worker testTimeout cannot interrupt ` +
          `(https://github.com/vitest-dev/vitest/issues/2920). Aborting the run.\n` +
          `Look for an infinite loop or runaway synchronous work in the tests, or raise the ` +
          `window via the BIT_VITEST_HANG_TIMEOUT env var for a legitimately long-running run.`
        );
        // Mark the process as failed. The run never completed, so Vitest never
        // set `process.exitCode`; without this the teardown fallback would
        // `process.exit()` with code 0 and the hang would be reported as a pass.
        process.exitCode = 1;
        // Terminate via Vitest's official API. `close()` would await the stuck
        // worker and never resolve (cf. angular/angular-cli#32832), so use
        // `exit()`, which force-tears-down via its teardownTimeout fallback.
        const ctx = hangGuard.ctx;
        if (ctx) void ctx.exit(true);
        else process.exit(1);
      }, 1000);
      hangTimer.unref?.();
    }

    const vitest = await runPromise;
    if (hangTimer) clearInterval(hangTimer);

    if (context.watch) {
      // hold the process
      await new Promise(() => {});
    }

    await vitest!.close();

    const files = vitest!.state.getFiles();
    const errors = [
      ...installErrors,
      ...Array.from(vitest!.state.errorsSet as Set<Error>),
    ];
    const result = getResultFromFiles(files, errors, this.opts, context);

    if ((viteConfig as any).test!.coverage) {
      await checkCoverageThresholds((viteConfig as any).test!.coverage, context, result);
    }

    return result;
  }

  async watch(context: TesterContext): Promise<Tests> {
    const viteConfig = await getConfig(this.configPath, context, this.depResolver, this.opts, true);
    applySpecPatterns(viteConfig, this.opts, context);

    const workerApi = this.vitestWorker.initiate(
      context.ui
        ? { stdout: true, stderr: true, stdin: true }
        : { stdout: false, stderr: false, stdin: false }
    );

    const onTestCompleteCb = proxy((files?: VitestFile[], errors?: unknown[]) => {
      if (!this.onTestRunCompleteCb || !files) return;
      const tests = getResultFromFiles(files || [], errors || [], this.opts, context);
      this.onTestRunCompleteCb(tests);
    });

    await workerApi.onTestComplete(onTestCompleteCb);
    await workerApi.watch(viteConfig);

    return {} as Tests;
  }
}